mapper.select:
SELECT c.id, c.content, c.owner_comment, c.article_id, c.guest_name, c.parent_id, c.status, c.reviewed_at, c.created_at FROM ( SELECT ranked.* FROM ( SELECT c2.*, ROW_NUMBER() OVER (PARTITION BY c2.parent_id ORDER BY c2.created_at ASC) AS rn FROM comments c2 WHERE c2.status = 'approved' AND c2.parent_id IN
#{id}
) ranked WHERE ranked.rn <= 50 ) c ORDER BY c.created_at ASC
